Plan: Use a global fork order and a separate short audit critical section.

```c
#include <pthread.h>
#include <assert.h>
static pthread_mutex_t forks[5],audit=PTHREAD_MUTEX_INITIALIZER;
static int ids[5],eating[5],finished;
static void *diner(void *p) {
    int i=*(int *)p,j=(i+1)%5,lo=i<j?i:j,hi=i<j?j:i;
    assert((pthread_mutex_lock(&forks[lo])) == 0); assert((pthread_mutex_lock(&forks[hi])) == 0);
    assert((pthread_mutex_lock(&audit)) == 0);
    assert(!eating[(i+4)%5] && !eating[(i+1)%5]); eating[i]=1;
    assert((pthread_mutex_unlock(&audit)) == 0);
    assert((pthread_mutex_lock(&audit)) == 0); eating[i]=0; ++finished;
    assert((pthread_mutex_unlock(&audit)) == 0);
    assert((pthread_mutex_unlock(&forks[hi])) == 0); assert((pthread_mutex_unlock(&forks[lo])) == 0); return NULL;
}
int main(void) {
    pthread_t t[5];
    for(int i=0;i<5;i++) { ids[i]=i; assert((pthread_mutex_init(&forks[i],NULL)) == 0); }
    for(int i=0;i<5;i++) assert((pthread_create(&t[i],NULL,diner,&ids[i])) == 0);
    for(int i=0;i<5;i++) assert((pthread_join(t[i],NULL)) == 0);
    assert(finished==5);
    for(int i=0;i<5;i++) assert((pthread_mutex_destroy(&forks[i])) == 0);
    assert((pthread_mutex_destroy(&audit)) == 0); return 0;
}
```

Why it is correct: Ordered fork acquisition removes circular wait; the shared fork excludes adjacent diners. No code acquires forks while holding audit, so audit adds no reverse dependency. Finite diners release both forks in the exit section.

