Plan: A dirty fork is yielded on request when its owner is not eating; the receiver gets it clean and dirties it after eating. Lower-ID initial owners give an acyclic starting precedence relation.

```c
#include <pthread.h>
#include <assert.h>
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv=PTHREAD_COND_INITIALIZER;
static int ends[3][2]={{0,1},{1,2},{0,2}},owner[3]={0,1,0};
static int dirty[3]={1,1,1},request[3]={-1,-1,-1},eating[3],ids[3],meals[3];
static int incident(int f,int i) { return ends[f][0]==i || ends[f][1]==i; }
static int have_all(int i) {
    for(int f=0;f<3;f++) if(incident(f,i) && owner[f]!=i) return 0;
    return 1;
}
static void ask(int i) {
    for(int f=0;f<3;f++) if(incident(f,i) && owner[f]!=i) request[f]=i;
}
static void deliver(void) {
    for(int f=0;f<3;f++) if(request[f]>=0 && dirty[f] && !eating[owner[f]]) {
        owner[f]=request[f]; request[f]=-1; dirty[f]=0;
    }
    assert((pthread_cond_broadcast(&cv)) == 0);
}
static void *diner(void *p) {
    int i=*(int *)p;
    for(int round=0;round<2;round++) {
        assert((pthread_mutex_lock(&m)) == 0);
        while(!have_all(i)) {
            ask(i); deliver();
            if(!have_all(i)) {
                ask(i); /* request a fork just yielded by this delivery */
                while(!have_all(i)) { assert((pthread_cond_wait(&cv,&m)) == 0); ask(i); deliver(); }
            }
        }
        eating[i]=1;
        for(int j=0;j<3;j++) if(j!=i) assert(!eating[j]);
        assert((pthread_mutex_unlock(&m)) == 0);
        assert((pthread_mutex_lock(&m)) == 0); ++meals[i]; eating[i]=0;
        for(int f=0;f<3;f++) if(incident(f,i)) { assert(owner[f]==i); dirty[f]=1; }
        deliver(); assert((pthread_mutex_unlock(&m)) == 0);
    } return NULL;
}
int main(void) {
    pthread_t t[3];
    for(int i=0;i<3;i++) { ids[i]=i; assert((pthread_create(&t[i],NULL,diner,&ids[i])) == 0); }
    for(int i=0;i<3;i++) { assert((pthread_join(t[i],NULL)) == 0); assert(meals[i]==2); }
    assert((pthread_cond_destroy(&cv)) == 0); assert((pthread_mutex_destroy(&m)) == 0); return 0;
}
```

Why it is correct: The mutex serializes simulated message handling, not an ordered two-fork acquisition protocol. Each fork has one owner and eating requires both incident forks; dirty/clean transfer rules preserve the protocol’s progress argument under reliable handling and scheduling. Every wait rechecks ownership. Finite diners still service requests through the shared delivery routine after their last meal.

