Plan: Keep a durable permit count; condition notifications only ask blocked acquirers to recheck it.

```c
#include <pthread.h>
#include <assert.h>
typedef struct { pthread_mutex_t m; pthread_cond_t cv; unsigned count; } Sem;
static Sem s={PTHREAD_MUTEX_INITIALIZER,PTHREAD_COND_INITIALIZER,2};
static int active,finished;
static pthread_mutex_t audit=PTHREAD_MUTEX_INITIALIZER;
static void down(Sem *x) {
    assert((pthread_mutex_lock(&x->m)) == 0);
    while(x->count==0) assert((pthread_cond_wait(&x->cv,&x->m)) == 0);
    --x->count; assert((pthread_mutex_unlock(&x->m)) == 0);
}
static void up(Sem *x) {
    assert((pthread_mutex_lock(&x->m)) == 0); ++x->count;
    assert((pthread_cond_signal(&x->cv)) == 0); assert((pthread_mutex_unlock(&x->m)) == 0);
}
static void *worker(void *p) {
    (void)p; down(&s); assert((pthread_mutex_lock(&audit)) == 0); ++active; assert(active<=2);
    assert((pthread_mutex_unlock(&audit)) == 0);
    assert((pthread_mutex_lock(&audit)) == 0); --active; ++finished;
    assert((pthread_mutex_unlock(&audit)) == 0); up(&s); return NULL;
}
int main(void) {
    pthread_t t[4]; for(int i=0;i<4;i++) assert((pthread_create(&t[i],NULL,worker,NULL)) == 0);
    for(int i=0;i<4;i++) assert((pthread_join(t[i],NULL)) == 0);
    assert(finished==4 && active==0 && s.count==2);
    assert((pthread_cond_destroy(&s.cv)) == 0); assert((pthread_mutex_destroy(&s.m)) == 0); assert((pthread_mutex_destroy(&audit)) == 0); return 0;
}
```

Why it is correct: down and up serialize count with s.m. While prevents over-admission after spurious or competing wakeups, and up changes the predicate before signaling. Workers return every acquired permit. This user-space wait/signal design demonstrates P/V without pretending cond_signal stores permits.

