Plan: Use a one-way open predicate so registration notifications cannot be lost.

```c
#include <pthread.h>
#include <assert.h>
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t start=PTHREAD_COND_INITIALIZER;
static int joined,open,ids[4],score[4];
static void *player(void *p) {
    int id=*(int *)p; assert((pthread_mutex_lock(&m)) == 0);
    if(++joined==4) { open=1; assert((pthread_cond_broadcast(&start)) == 0); }
    while(!open) assert((pthread_cond_wait(&start,&m)) == 0);
    assert(joined==4); assert((pthread_mutex_unlock(&m)) == 0);
    score[id]=(id+1)*(id+1); return NULL;
}
int main(void) {
    pthread_t t[4];
    for(int i=0;i<4;i++) { ids[i]=i; assert((pthread_create(&t[i],NULL,player,&ids[i])) == 0); }
    for(int i=0;i<4;i++) assert((pthread_join(t[i],NULL)) == 0);
    int total=0; for(int i=0;i<4;i++) total+=score[i]; assert(total==30);
    assert((pthread_cond_destroy(&start)) == 0); assert((pthread_mutex_destroy(&m)) == 0); return 0;
}
```

Why it is correct: The fourth registration changes open before broadcasting. Earlier arrivals wait while false; later arrivals observe the durable true value. Each score slot has one owner and is read by main only after join.

