Verdict: bug found

Line 24: `(void)p; ck(pthread_mutex_lock(&m)); P(empty);`

The producer waits for space while owning the queue mutex, trapping the remover behind that mutex.

| Step | Thread A | Thread B | Shared state |
|---|---|---|---|
| 1 | lock(m) succeeds |  | m=A; slot full |
| 2 | P(empty) blocks |  | A holds m |
| 3 |  | P(full) succeeds | B reserves the old parcel |
| 4 |  | lock(m) blocks | A needs B’s removal; B needs m |

Fix:
```diff
--- prog.c
+++ prog.c (fixed)
@@ -21,7 +21,7 @@
 static sem_t empty,full;
 static int parcel=9;
 static void *a(void *p) {
-    (void)p; ck(pthread_mutex_lock(&m)); P(empty);
+    (void)p; P(empty); ck(pthread_mutex_lock(&m));
     parcel=10; ck(pthread_mutex_unlock(&m)); V(full); return NULL;
 }
 static void *b(void *p) {
```

Reserve space with wait(P) before entering the mutex critical section; the remover can then release the old slot and signal(V) empty.

Verdict: bug found

Line 24: `if(depth>0) visit(depth-1);`

Each recursive call repeats normal-mutex acquisition while its ancestor still owns m.

| Step | Thread A | Thread B | Shared state |
|---|---|---|---|
| 1 | visit(2) locks m |  | m=A |
| 2 | visit(1) tries to lock m |  | recursive call waits for its own caller |

Fix:
```diff
--- prog.c
+++ prog.c (fixed)
@@ -20,11 +20,10 @@
 static pthread_mutex_t m;
 static int visited;
 static void visit(int depth) {
-    ck(pthread_mutex_lock(&m));
     if(depth>0) visit(depth-1);
-    ++visited; ck(pthread_mutex_unlock(&m));
+    ++visited;
 }
-static void *a(void *p) { (void)p; visit(2); return NULL; }
+static void *a(void *p) { (void)p; ck(pthread_mutex_lock(&m)); visit(2); ck(pthread_mutex_unlock(&m)); return NULL; }
 static void *b(void *p) { return a(p); }
 int main(void) {
     pthread_t x,y;
```

One outer entry protects the whole walk; the recursive helper performs no lock acquisition and the wrapper executes one exit. It remains safe because all callers use the wrapper.

Verdict: bug found

Line 24: `(void)p; int first=atomic_fetch_xor(&reverse,1),second=1-first;`

An atomic order selector is race-free but gives different callers incompatible acquisition orders. Atomic selection does not make a lock hierarchy consistent.

| Step | Thread A | Thread B | Shared state |
|---|---|---|---|
| 1 | fetch_xor returns 0 |  | A selects gate0 then gate1 |
| 2 |  | fetch_xor returns 1 | B selects gate1 then gate0 |
| 3 | lock(gate0) succeeds |  | gate0=A |
| 4 |  | lock(gate1) succeeds | gate1=B |
| 5 | lock(gate1) blocks |  | A waits |
| 6 |  | lock(gate0) blocks | cycle |

Fix:
```diff
--- prog.c
+++ prog.c (fixed)
@@ -18,17 +18,16 @@
 #define P(s) do { int e; do { e=sem_wait(&(s)); } while (e==-1 && errno==EINTR); if (e==-1) { perror("sem_wait"); exit(1); } } while (0)
 #define V(s) SO(sem_post(&(s)))
 static pthread_mutex_t gate[2]={PTHREAD_MUTEX_INITIALIZER,PTHREAD_MUTEX_INITIALIZER};
-static atomic_int reverse;
 static int leases;
 static void *a(void *p) {
-    (void)p; int first=atomic_fetch_xor(&reverse,1),second=1-first;
+    (void)p; int first=0,second=1;
     ck(pthread_mutex_lock(&gate[first])); ck(pthread_mutex_lock(&gate[second]));
     ++leases; ck(pthread_mutex_unlock(&gate[second])); ck(pthread_mutex_unlock(&gate[first])); return NULL;
 }
 static void *b(void *p) { return a(p); }
 int main(void) {
     pthread_t x,y;
-    atomic_init(&reverse,0);
+    
     ck(pthread_create(&x,NULL,a,NULL));
     ck(pthread_create(&y,NULL,b,NULL));
     ck(pthread_join(x,NULL));
```

Use a fixed global order rather than an alternating preference. That removes circular wait without relying on scheduling luck.

Verdict: bug found

Line 23: `while(busy) {}`
Line 24: `busy=1;`
Line 26: `busy=0;`

Separate ordinary test and set operations do not form an atomic entry section. busy itself races and both contenders can reach conflicting owner accesses.

| Step | Thread A | Thread B | Shared state |
|---|---|---|---|
| 1 | read busy -> 0 |  | gate appears free |
| 2 |  | read busy -> 0 | both contenders passed check |
| 3 | store busy=1 |  | A thinks it owns gate |
| 4 |  | store busy=1 | B also thinks it owns gate |

Fix:
```diff
--- prog.c
+++ prog.c (fixed)
@@ -20,10 +20,9 @@
 static unsigned char busy;
 static int owner=-1;
 static void claim(int id) {
-    while(busy) {}
-    busy=1;
+    while(__atomic_test_and_set(&busy,__ATOMIC_ACQUIRE)) {}
     if(owner==-1) owner=id;
-    busy=0;
+    __atomic_clear(&busy,__ATOMIC_RELEASE);
 }
 static void *a(void *p) { (void)p; claim(0); return NULL; }
 static void *b(void *p) { (void)p; claim(1); return NULL; }
```

Atomic test-and-set grants entry to one observer of the clear byte, and release-clear hands off protected state. This provides exclusion, not FIFO fairness.

Verdict: bug found

Line 30: `ck(pthread_mutex_destroy(&job->m)); free(job);`

The job’s storage and embedded mutex are released before the worker finishes. That combines an invalid mutex lifecycle with a possible later use-after-free.

| Step | Thread A | Thread B | Shared state |
|---|---|---|---|
| 1 | worker owns job mutex |  | job is live and in use |
| 2 | V(acquired) |  | main may proceed |
| 3 |  | destroy job mutex | invalid destruction of owned object |
| 4 |  | free(job) | worker still holds a pointer into freed storage |

Fix:
```diff
--- prog.c
+++ prog.c (fixed)
@@ -27,7 +27,7 @@
 int main(void) {
     pthread_t t; job=malloc(sizeof *job); assert(job); job->value=3; ck(pthread_mutex_init(&job->m,NULL));
     SO(sem_init(&acquired,0,0)); SO(sem_init(&finish,0,0)); ck(pthread_create(&t,NULL,worker,NULL)); P(acquired);
+    V(finish); ck(pthread_join(t,NULL));
     ck(pthread_mutex_destroy(&job->m)); free(job);
-    V(finish); ck(pthread_join(t,NULL));
     SO(sem_destroy(&acquired)); SO(sem_destroy(&finish)); return 0;
 }
```

Keep the entire job alive through the finish handshake and join. Only after the worker’s final unlock can main destroy the embedded mutex and free its enclosing allocation.

Verdict: bug found

Line 23: `if(id<0) { ck(pthread_mutex_unlock(&m)); return; }`

The rejected input returns a key it never acquired. A default mutex’s non-owner unlock must not be treated as a harmless cleanup operation.

| Step | Thread A | Thread B | Shared state |
|---|---|---|---|
| 1 | test id<0 -> true |  | A has not acquired m |
| 2 | unlock(m) without entry |  | invalid ownership; no portable default-mutex semantics |

Fix:
```diff
--- prog.c
+++ prog.c (fixed)
@@ -20,7 +20,7 @@
 static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
 static int records;
 static void record(int id) {
-    if(id<0) { ck(pthread_mutex_unlock(&m)); return; }
+    if(id<0) return;
     ck(pthread_mutex_lock(&m)); ++records; ck(pthread_mutex_unlock(&m));
 }
 static void *a(void *p) { (void)p; record(-1); return NULL; }
```

Validation occurs before the entry section, so rejection should simply return. Only the successful acquisition path needs the matching exit unlock.

Verdict: bug found

Line 22: `(void)p; int snapshot=arrivals;`
Line 23: `while(snapshot<2) {}`

Even the idealized schedule cannot change A’s local snapshot. In addition, the initial ordinary read is not synchronized with B’s write.

| Step | Thread A | Thread B | Shared state |
|---|---|---|---|
| 1 | copy arrivals -> snapshot=0 |  | local snapshot fixed at 0 |
| 2 |  | arrivals=2 | shared state changed |
| 3 | test snapshot<2 -> true |  | loop never reloads shared state |

Fix:
```diff
--- prog.c
+++ prog.c (fixed)
@@ -17,13 +17,13 @@
 #define SO(x) do { if ((x)==-1) { perror(#x); exit(1); } } while (0)
 #define P(s) do { int e; do { e=sem_wait(&(s)); } while (e==-1 && errno==EINTR); if (e==-1) { perror("sem_wait"); exit(1); } } while (0)
 #define V(s) SO(sem_post(&(s)))
-static int arrivals;
+static atomic_int arrivals;
 static void *a(void *p) {
-    (void)p; int snapshot=arrivals;
-    while(snapshot<2) {}
+    (void)p;
+    while(atomic_load_explicit(&arrivals,memory_order_relaxed)<2) {}
     return NULL;
 }
-static void *b(void *p) { (void)p; arrivals=2; return NULL; }
+static void *b(void *p) { (void)p; atomic_store_explicit(&arrivals,2,memory_order_relaxed); return NULL; }
 int main(void) {
     pthread_t x,y;

```

Make arrivals atomic and load it inside the loop. The controller’s finite store can then be observed instead of polling an immutable local copy.
